#include "case_link.h"
#include <stdio.h>
#include <string.h>
static void w16(unsigned char*p,unsigned x){p[0]=x;p[1]=x>>8;}
static void w32(unsigned char*p,unsigned x){w16(p,x);w16(p+2,x>>16);}
static void thermal(unsigned char*p,unsigned seq,unsigned flags,unsigned start,unsigned done,int temp){memset(p,0,20);p[0]=1;p[1]=flags;w16(p+2,seq);w32(p+4,1);w32(p+8,start);w32(p+12,done);w16(p+16,(unsigned short)temp);w16(p+18,65535);}
int main(void){case_link s;cl_policy p={.thermal_fresh_ms=2000,.ratio_fresh_ms=2000,.max_attempt_ms=1000,.max_gap_ms=10000,.max_anchor_age_ms=10000,.max_round_trip_ms=2000,.combined_clock_drift_ppm=100,.combined_timer_resolution_ms=1,.max_sequence_advance=1};for(unsigned i=0;i<CL_CHARGE_FIELDS;i++)p.charge_fresh_ms[i]=2000;case_link_init(&s,123,&p,0);unsigned epoch=case_link_connect(&s,0);unsigned char f[20],q[20];case_link_command(&s,1,0,0,10,q);memset(f,0,20);f[0]=1;w16(f+2,q[2]|(q[3]<<8));w32(f+4,1);w32(f+8,1012);w32(f+12,1015);w32(f+16,123);case_link_feed(&s,epoch,CL_RESULT,f,20,20);case_link_command(&s,2,0,0,25,q);w16(f+2,q[2]|(q[3]<<8));w32(f+8,1028);w32(f+12,1030);case_link_feed(&s,epoch,CL_RESULT,f,20,35);thermal(f,10,0,2000,0,-32768);printf("unfinished=%d\n",case_link_feed(&s,epoch,CL_THERMAL,f,20,1000));thermal(f,11,3,2200,2250,3700);printf("newer=%d\n",case_link_feed(&s,epoch,CL_THERMAL,f,20,1255));thermal(f,10,3,2000,2300,2000);printf("older_completion=%d\n",case_link_feed(&s,epoch,CL_THERMAL,f,20,1305));cl_value v=case_link_temperature(&s,1305);printf("latest_value=%d,newest_sequence=%u,resync=%d,quality=%d\n",v.value,s.thermal_order.newest,s.resync_needed,v.quality);thermal(f,12,67,2000,2100,2400);case_link_feed(&s,epoch,CL_THERMAL,f,20,2100);memset(f,0,20);f[0]=1;f[1]=29;w16(f+2,1);w32(f+4,1);w32(f+8,2000);w32(f+12,2000);w32(f+16,2100);printf("equal_loss_start=%d\n",case_link_feed(&s,epoch,CL_SOURCE,f,20,2110));cl_event_view e;case_link_event(&s,1,&e);printf("equal_loss_attempt_matches=%d\n",e.source_attempt_matched);return 0;}
